/* Hausa meanings for Hisnul Muslim duas, keyed by dua id. Needs review by a Hausa-speaking scholar before wide release. */
"use strict";
window.LML_HISNUL_HAUSA = {
 "dua-000001": "Dukkan godiya ta tabbata ga Allah, wanda Ya rayar da mu bayan ya karɓi rayukanmu, kuma gare Shi ne tashin kiyama.",
 "dua-000002": "Babu abin bautawa da gaskiya sai Allah, Shi kaɗai, babu abokin tarayya gare Shi. Mulki da godiya duka nasa ne, kuma Shi Mai iko ne a kan kome. Tsarki ya tabbata ga Allah, dukkan godiya ta tabbata ga Allah, babu abin bautawa da gaskiya sai Allah, Allah ne Mafi girma, babu dabara ko ƙarfi sai da taimakon Allah, Mai girma, Madaukaki. Ya Ubangijina, ka gafarta mini.",
 "dua-000003": "Dukkan godiya ta tabbata ga Allah, wanda Ya mayar mini da lafiyata, Ya dawo mini da raina, kuma Ya ba ni damar ambatonSa.",
 "dua-000005": "Dukkan godiya ta tabbata ga Allah, wanda Ya suturta ni da wannan tufa, Ya kuma azurta ni da ita, ba tare da wani ƙarfi ko dabara daga gare ni ba.",
 "dua-000006": "Ya Allah, gare Ka ne dukkan godiya. Kai ne Ka suturta ni da ita, ina roƙonKa alherinta da alherin da aka yi ta saboda shi, kuma ina neman tsari gare Ka daga sharrinta da sharrin da aka yi ta saboda shi.",
 "dua-000007": "Ka sa ta tsufa, Allah kuma Ya maye maka da wata.",
 "dua-000008": "Ka sa sabuwa, ka rayu cikin kyawawan halaye, ka mutu a matsayin shahidi.",
 "dua-000009": "Da sunan Allah.",
 "dua-000010": "Da sunan Allah. Ya Allah, ina neman tsari gare Ka daga dukkan sharri da masu aikata sharri.",
 "dua-000011": "Ina roƙon Allah gafara.",
 "dua-000012": "Da sunan Allah.",
 "dua-000013": "Ina shaida cewa babu abin bautawa da gaskiya sai Allah, Shi kaɗai, babu abokin tarayya gare Shi, kuma ina shaida cewa Muhammadu bawanSa ne kuma Manzonsa ne.",
 "dua-000014": "Ya Allah, ka sa ni cikin waɗanda suke komawa gare Ka da tuba akai-akai, ka sa ni cikin waɗanda suke tsarkakakku.",
 "dua-000015": "Tsarki ya tabbata a gare Ka, ya Allah, ina yabonKa. Ina shaida cewa babu abin bautawa da gaskiya sai Kai. Ina neman gafararKa, kuma ina tuba zuwa gare Ka.",
 "dua-000016": "Da sunan Allah, na dogara ga Allah, kuma babu dabara ko ƙarfi sai da taimakon Allah.",
 "dua-000017": "Ya Allah, ina neman tsari gare Ka kada in ɓata ko a ɓatar da ni, ko in zame ko a sa ni yin tuntuɓe, ko in zalunta ko a zalunce ni, ko in aikata wauta ko a yi mini wauta.",
 "dua-000018": "Da sunan Allah mun shiga, da sunan Allah mun fita, kuma ga Ubangijinmu muke dogara.",
 "dua-000020": "Ina neman tsari da Allah Maɗaukaki, da Fuskarsa mai daraja, da ikonsa na har abada daga shaiɗan la'ananne. Da sunan Allah, salati da amincin Allah su tabbata ga Manzon Allah. Ya Allah, ka buɗe mini ƙofofin rahamarKa.",
 "dua-000021": "Da sunan Allah, salati da amincin Allah su tabbata ga Manzon Allah. Ya Allah, ina roƙon falalarKa. Ya Allah, ka kiyaye ni daga shaiɗan la'ananne.",
 "dua-000022": "\"Babu dabara ko ƙarfi sai da taimakon Allah.\"",
 "dua-000023": "\"Ni ma ina shaida cewa babu abin bautawa da gaskiya sai Allah, Shi kaɗai, babu abokin tarayya gare Shi, kuma Muhammadu bawanSa ne kuma Manzonsa ne. Na yarda da Allah a matsayin Ubangiji, da Muhammadu a matsayin Manzo, da Musulunci a matsayin addini.\"",
 "dua-000024": "\"Ya Allah, Ubangijin wannan cikakkiyar kira da wannan sallah da za a yi, ka ba Muhammadu wasila da falala, ka tashe shi a wurin yabo da Ka yi masa alkawari. Lalle Kai ba ka saɓa alkawari.\"",
 "dua-000025": "Ya Allah, ka nisantar da ni daga zunubaina kamar yadda Ka nisantar da Gabas daga Yamma. Ya Allah, ka tsarkake ni daga zunubaina kamar yadda ake tsarkake farin riga daga dattin. Ya Allah, ka wanke ni daga zunubaina da dusar ƙanƙara, da ruwa, da ƙanƙara.",
 "dua-000026": "Tsarki ya tabbata a gare Ka, ya Allah, ina yabonKa. Albarkacin sunanKa, kuma darajarKa ta ɗaukaka, babu abin bautawa da gaskiya sai Kai.",
 "dua-000027": "Na karkata fuskata ga Wanda Ya ƙaga sammai da ƙasa, ni ba ɗaya ne daga cikin masu haɗa wasu da Allah ba. Lalle sallata, da hadayata, da rayuwata, da mutuwata, na Allah ne, Ubangijin talikai, babu abokin tarayya a gare Shi, kuma da wannan aka umarce ni, ni kuma ina daga cikin Musulmai. Ya Allah, Kai ne Sarki, babu abin bautawa da gaskiya sai Kai. Kai ne Ubangijina, ni kuma bawanKa ne. Na zalunci kaina, kuma na amince da zunubina, don haka ka gafarta mini dukkan zunubaina, domin babu wanda yake gafarta zunubai sai Kai. Ka shiryar da ni zuwa ga mafi kyawun halaye, domin babu wanda zai shiryar da ni zuwa gare su sai Kai, kuma ka kiyaye ni daga mafi munin halaye, domin babu wanda zai kiyaye ni daga gare su sai Kai. Ga ni, ina amsa kiranKa, mai farin ciki da yi maka hidima. Dukkan alheri yana hannunKa, sharri kuma ba daga gare Ka yake ba. Ina rayuwa ta hanyar nufinKa, kuma zan koma gare Ka. Mai albarka ne kuma Mai ɗaukaka, ina neman gafararKa kuma ina tuba zuwa gare Ka.",
 "dua-000028": "Ya Allah, Ubangijin Jibrilu da Mika'ilu da Israfil, mala'iku masu girma, Mahaliccin sammai da ƙasa, Masani ga abin gani da abin ɓoye. Kai ne mai yanke hukunci tsakanin bayinKa a cikin abin da suka saɓa a kansa. Ka shiryar da ni zuwa ga gaskiya da izininKa, a cikin abin da suka sabawa, domin lalle Kai kana shiryar da wanda Ka so zuwa hanya madaidaiciya.",
 "dua-000029": "Allah ne Mafi girma.",
 "dua-000030": "Godiya ta yawaita ga Allah.",
 "dua-000031": "Ina tsarkake Allah da safe da yamma.",
 "dua-000032": "Ina neman tsari da Allah daga shaiɗan, daga girmankansa, da waƙoƙinsa, da haukansa.",
 "dua-000033": "Ya Allah, gare Ka ne dukkan godiya, Kai ne Hasken sammai da ƙasa da abin da ke cikinsu. Gare Ka ne dukkan godiya, Kai ne Mai riƙe sammai da ƙasa da abin da ke cikinsu. Gare Ka ne dukkan godiya. Kai ne Ubangijin sammai da ƙasa da abin da ke cikinsu. Gare Ka ne dukkan godiya, da mulkin sammai da ƙasa da abin da ke cikinsu. Gare Ka ne dukkan godiya, Kai ne Sarkin sammai da ƙasa, kuma gare Ka ne dukkan godiya. Kai ne Gaskiya, alkawarinKa gaskiya ne, maganarKa gaskiya ce, ganinKa gaskiya ne, aljanna gaskiya ce, wuta gaskiya ce, annabawa gaskiya ne, Muhammadu gaskiya ne, kuma tashin ƙiyama gaskiya ne. Ya Allah, gare Ka na miƙa wuya, da Kai na dogara, da Kai na yi imani, kuma gare Ka na komo da tuba.",
 "dua-000034": "Tsarki ya tabbata ga Ubangijina, Mafi girma.",
 "dua-000035": "Tsarki ya tabbata a gare Ka, ya Allah, Ubangijinmu, ina yabonKa. Ya Allah, ka gafarta mini.",
 "dua-000036": "Tsarkakakke ne kuma mai tsarki, Ubangijin mala'iku da Ruhu, watau Jibrilu.",
 "dua-000037": "Ya Allah, gare Ka na rusuna, da Kai na yi imani, kuma gare Ka na miƙa wuya. Jina, ganina, hankalina, ƙasusuwana, jijiyoyina, da abin da ƙafafuna suke ɗauka, duk suna ƙasƙantar da kansu a gabanKa.",
 "dua-000038": "Tsarki ya tabbata gare Shi, Mai iko kan komai, Mai mulki, Mai girma da daraja.",
 "dua-000039": "Allah ya amsa wanda ya yabe Shi.",
 "dua-000040": "Ubangijinmu, gare Ka ne dukkan godiya, godiya mai yawa, mai kyau, mai albarka.",
 "dua-000046": "Tsarki ya tabbata gare Shi, Mai iko kan komai, Mai mulki, Mai girma da daraja.",
 "dua-000047": "Ya Allah, ka gafarta mini dukkan zunubaina, ƙanana da manya, na farko da na ƙarshe, da na bayyane da na ɓoye.",
 "dua-000048": "Ya Allah, ina neman tsari da yardarKa daga fushinKa, da gafararKa daga azabarKa, kuma ina neman tsari gare Ka daga Gare Ka. Ba zan iya ƙidaya yabonKa ba, Kai kamar yadda Ka yabi kanKa ne.",
 "dua-000049": "Ubangijina, ka gafarta mini. Ubangijina, ka gafarta mini.",
 "dua-000050": "Ya Allah, ka gafarta mini, ka yi mini rahama, ka shiryar da ni, ka wadata ni, ka ba ni lafiya, ka azurta ni, ka ɗaukaka darajata.",
 "dua-000051": "Fuskata ta faɗi a rusuna ga Wanda Ya halicce ta, Ya ba ta ji da gani, da ikonSa da ƙarfinSa. Don haka tsarki ya tabbata ga Allah, Mafi kyawun masu halitta.",
 "dua-000052": "Ya Allah, ka rubuta mini lada saboda wannan sujjada, ka share mini zunubi, ka ajiye mini ita, ka karɓe ta daga gare ni kamar yadda Ka karɓe ta daga bawanKa Dawud.",
 "dua-000053": "Dukkan ibada, da addu'o'i, da kyawawan ayyuka na Allah ne. Salama, da rahama, da albarkar Allah su tabbata a gare ka, ya Annabi. Salama ta tabbata a kanmu da bayin Allah masu adalci. Ina shaida cewa babu abin bautawa da gaskiya sai Allah, kuma ina shaida cewa Muhammadu bawanSa ne kuma Manzonsa ne.",
 "dua-000054": "Ya Allah, ka aika da salati ga Muhammadu da mabiyan Muhammadu, kamar yadda Ka aika da salati ga Ibrahim da mabiyan Ibrahim. Lalle Kai Mai yabo ne, Mai girma. Ya Allah, ka aika da albarka ga Muhammadu da iyalan Muhammadu, kamar yadda Ka aika da albarka ga Ibrahim da iyalan Ibrahim. Lalle Kai Mai yabo ne, Mai girma.",
 "dua-000055": "Ya Allah, ka aika da salati ga Muhammadu da matan Muhammadu da zuriyarsa, kamar yadda Ka aika da salati ga iyalan Ibrahim. Ka kuma aika da albarka ga Muhammadu da matan Muhammadu da zuriyarsa, kamar yadda Ka aika da albarka ga iyalan Ibrahim. Lalle Kai Mai yabo ne, Mai girma.",
 "dua-000056": "Ya Allah, ina neman tsari gare Ka daga azabar kabari, da azabar Wuta, da fitintinun rayuwa da mutuwa, da mugun gwajin Al-Masihu Ad-Dajjal.",
 "dua-000057": "Ya Allah, ina neman tsari gare Ka daga azabar kabari, kuma ina neman tsari gare Ka daga jarabawa da fitinar Al-Masihu Ad-Dajjal, kuma ina neman tsari gare Ka daga fitintinun rayuwa da mutuwa. Ya Allah, ina neman tsari gare Ka daga zunubi da bashi.",
 "dua-000058": "Ya Allah, lalle na zalunci kaina sosai, kuma babu wanda zai gafarta zunubai sai Kai. Don haka ka gafarta mini gafara daga gare Ka, ka yi mini rahama. Lalle Kai ne Mai yawan gafara, Mai jinƙai.",
 "dua-000059": "Ya Allah, ka gafarta mini zunuban da suka riga suka faru da waɗanda za su faru nan gaba, da waɗanda na aikata a ɓoye da waɗanda na aikata a fili, da waɗanda na wuce iyaka a cikinsu, da waɗanda Ka fi sani fiye da ni. Kai ne Mai gabatarwa, Kai ne Mai jinkirtawa. Babu abin bautawa da gaskiya sai Kai.",
 "dua-000060": "Ya Allah, ka taimake ni in tuna Ka, in gode maka, kuma in bauta maka da kyau.",
 "dua-000061": "Ya Allah, ina neman tsari gare Ka daga rowa da rashin jarumta. Ina neman tsari gare Ka kada a mayar da ni zuwa mafi munin rayuwa, watau tsufa, da rauni, da rashin iya aiki, da tsoro. Kuma ina neman tsari gare Ka daga fitintinun wannan rayuwa da azabar kabari.",
 "dua-000062": "Ya Allah, ina roƙonKa ka ba ni Aljanna, kuma ina neman tsari gare Ka daga Wuta.",
 "dua-000063": "Ya Allah, da saninKa na gaibi da ikonKa a kan halitta, ka rayar da ni muddin Ka sani rayuwa tana da kyau a gare ni, ka karɓe ni idan Ka sani mutuwa ta fi kyau a gare ni. Ya Allah, ka sa ni in ji tsoronKa a ɓoye da a fili, kuma ina roƙonKa ka sa ni in faɗi gaskiya a lokacin farin ciki da fushi. Ina roƙonKa ka sa ni in yi matsakaici a lokacin wadata da talauci, kuma ina roƙonKa jin daɗi da farin ciki da ba zai ƙare ba. Ina roƙonKa ka sa ni in yarda da abin da Ka ƙaddara, da rayuwa mai sauƙi bayan mutuwa. Ina roƙonKa daɗin kallon fuskarKa, da marmarin haɗuwa da Kai, ba tare da cutarwa mai cutarwa ko fitina mai ɓata ba. Ya Allah, ka ƙawata mu da adon imani, ka sa mu cikin waɗanda suke shiryarwa kuma aka shiryar da su.",
 "dua-000064": "Ya Allah, ina roƙonKa, domin Kai ne Ɗaya, Kai kaɗai, As-Samad, Wanda ba Ya haifuwa, kuma ba a haife Shi ba, kuma babu wani abu mai kama da Shi. Ka gafarta mini zunubaina, lalle Kai ne Mai yawan gafara, Mai jinƙai.",
 "dua-000065": "Ya Allah, ina roƙonKa, domin gare Ka ne dukkan yabo. Babu abin bautawa da gaskiya sai Kai, Kai kaɗai, babu abokin tarayya gare Ka. Kai ne Mai ba da kyauta. Ya Mahaliccin sammai da ƙasa, Ya Mai girma da karimci, Ya Mai rai har abada, Ya Mai tsayuwa da kanKa, kuma Mai riƙe kowa, lalle ina roƙonKa Aljanna, kuma ina neman tsari gare Ka daga Wuta.",
 "dua-000066": "Ya Allah, ina roƙonKa, domin ina shaida cewa Kai ne Allah, babu abin bautawa da gaskiya sai Kai, Ɗaya, As-Samad, wanda ba Ya haifuwa, kuma ba a haife Shi ba, kuma babu wani abu mai kama da Shi.",
 "dua-000067": "Ina neman gafarar Allah.",
 "dua-000068": "Ya Allah, Kai ne As-Salam, kuma daga gare Ka ne salama take. Albarkacin Kai, Ya Mai girma da karimci.",
 "dua-000069": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome.",
 "dua-000070": "Ya Allah, babu wanda zai hana abin da Ka bayar, babu wanda zai bayar da abin da Ka hana, kuma babu dukiya ko matsayi da zai amfani mai shi a gabanKa.",
 "dua-000071": "Babu abin bautawa da gaskiya sai Allah, Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome. Babu dabara ko ƙarfi sai da taimakon Allah. Babu abin bautawa da gaskiya sai Allah, kuma ba mu bautawa kowa sai Shi. Gare Shi ne alheri, da falala, da kyakkyawan yabo. Babu abin bautawa da gaskiya sai Allah, kuma mun tsarkake addininmu gare Shi, ko da kafirai sun ƙi hakan.",
 "dua-000072": "Tsarki ya tabbata ga Allah.",
 "dua-000073": "Dukkan godiya ta tabbata ga Allah.",
 "dua-000074": "Allah ne Mafi girma.",
 "dua-000075": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome.",
 "dua-000076": "Da sunan Allah, Mai rahama, Mai jinƙai. 112:1 Ka ce: Shi ne Allah, Ɗaya. 112:2 Allah, Wanda dukkan halitta ke nufinSa. 112:3 Ba Ya haifuwa, kuma ba a haife Shi ba. 112:4 Babu wani abu mai kama da Shi. Da sunan Allah, Mai rahama, Mai jinƙai. 113:1 Ka ce: Ina neman tsari da Ubangijin safiya, 113:2 daga sharrin abin da Ya halitta, 113:3 daga sharrin duhu idan ya yi yawa, 113:4 daga sharrin masu busawa cikin ƙulli, 113:5 da sharrin mai hassada idan ya yi hassada. Da sunan Allah, Mai rahama, Mai jinƙai. 114:1 Ka ce: Ina neman tsari da Ubangijin mutane, 114:2 Sarkin mutane, 114:3 Abin bautawar mutane, 114:4 daga sharrin mai waswasi mai ja da baya, 114:5 wanda yake waswasi a cikin zukatan mutane, 114:6 daga aljanu da mutane.",
 "dua-000077": "Allah! Babu abin bautawa da gaskiya sai Shi, Mai rai, Mai tsayar da komai. Barci ko bacci ba sa kama Shi. Duk abin da ke cikin sammai da ƙasa nasa ne. Wa zai iya yin ceto a wurinSa sai da izininSa? Yana sane da abin da ke gabansu da abin da ke bayansu, kuma ba sa sanin komai daga iliminSa sai abin da Ya so. KursiyyinSa ya kewaye sammai da ƙasa, kuma kiyaye su ba ya gajiyar da Shi. Shi ne Maɗaukaki, Mai girma.",
 "dua-000078": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo. Yana ba da rai, kuma Yana kashe, kuma Shi Mai iko ne a kan kome.",
 "dua-000079": "Ya Allah, ina roƙonKa ilimi mai amfani, da arziki mai kyau, da ayyuka karɓaɓɗu.",
 "dua-000080": "\"Ya Allah, ina neman shawararKa ta hanyar saninKa, kuma da ikonKa nake neman ƙarfi, ina roƙonKa daga falalarKa mai girma, domin lalle Kai kana iya, ni kuwa ba na iya, Kai kana sani, ni kuwa ba na sani ba, kuma Kai ne Masanin gaibi. Ya Allah, idan Ka sani wannan al'amari [al'amarin da kake nema] alheri ne a gare ni ta fuskar addinina, da rayuwata, da ƙarshen al'amarina, to ka ƙaddara shi a gare ni, ka sauƙaƙa mini shi, sannan ka albarkace ni da shi. Idan kuma Ka sani wannan al'amari [al'amarin da kake nema] sharri ne a gare ni ta fuskar addinina, da rayuwata, da ƙarshen al'amarina, to ka kawar da shi daga gare ni, ka kawar da ni daga gare shi, ka ƙaddara mini alheri duk inda yake, sannan ka sa ni in gamsu da shi.\"",
 "dua-000262": "\"Ya Allah, ina neman shawararKa ta hanyar saninKa, kuma da ikonKa nake neman ƙarfi, ina roƙonKa daga falalarKa mai girma, domin lalle Kai kana iya, ni kuwa ba na iya, Kai kana sani, ni kuwa ba na sani ba, kuma Kai ne Masanin gaibi. Ya Allah, idan Ka sani wannan al'amari [al'amarin da kake nema] alheri ne a gare ni ta fuskar sakamakon gaggawa da na ƙarshe na al'amarina, to ka ƙaddara shi a gare ni, ka sauƙaƙa mini shi, sannan ka albarkace ni da shi. Idan kuma Ka sani wannan al'amari [al'amarin da kake nema] sharri ne a gare ni ta fuskar sakamakon gaggawa da na ƙarshe na al'amarina, to ka kawar da shi daga gare ni, ka kawar da ni daga gare shi, ka ƙaddara mini alheri duk inda yake, sannan ka sa ni in gamsu da shi.\"",
 "dua-000081": "Ina neman tsari da Allah daga shaiɗan la'ananne. Allah! Babu abin bautawa da gaskiya sai Shi, Mai rai, Mai tsayar da komai. Barci ko bacci ba sa kama Shi. Duk abin da ke cikin sammai da ƙasa nasa ne. Wa zai iya yin ceto a wurinSa sai da izininSa? Yana sane da abin da ke gabansu da abin da ke bayansu, kuma ba sa sanin komai daga iliminSa sai abin da Ya so. Kursiyyinsa ya kewaye sammai da ƙasa, kuma kiyaye su ba ya gajiyar da Shi. Shi ne Maɗaukaki, Mai girma.",
 "dua-000082": "Da sunan Allah, Mai rahama, Mai jinƙai. 112:1 Ka ce: Shi ne Allah, Ɗaya. 112:2 Allah, Wanda dukkan halitta ke nufinSa. 112:3 Ba Ya haifuwa, kuma ba a haife Shi ba. 112:4 Babu wani abu mai kama da Shi. Da sunan Allah, Mai rahama, Mai jinƙai. 113:1 Ka ce: Ina neman tsari da Ubangijin safiya, 113:2 daga sharrin abin da Ya halitta, 113:3 daga sharrin duhu idan ya yi yawa, 113:4 daga sharrin masu busawa cikin ƙulli, 113:5 da sharrin mai hassada idan ya yi hassada. Da sunan Allah, Mai rahama, Mai jinƙai. 114:1 Ka ce: Ina neman tsari da Ubangijin mutane, 114:2 Sarkin mutane, 114:3 Abin bautawar mutane, 114:4 daga sharrin mai waswasi mai ja da baya, 114:5 wanda yake waswasi a cikin zukatan mutane, 114:6 daga aljanu da mutane.",
 "dua-000083": "Mun shiga safiya, kuma duk mulki na Allah ne. Dukkan godiya ta tabbata ga Allah. Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome. Ya Ubangijina, ina roƙonKa alherin wannan yini da abin da zai biyo baya. Ina neman tsari gare Ka daga sharrin wannan yini da abin da zai biyo baya. Ya Ubangijina, ina neman tsari gare Ka daga kasala da munin tsufa. Ya Ubangijina, ina neman tsari gare Ka daga azabar Wuta da azabar kabari.",
 "dua-000084": "Mun shiga yamma, kuma duk mulki na Allah ne. Dukkan godiya ta tabbata ga Allah. Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome. Ya Ubangijina, ina roƙonKa alherin wannan dare da abin da zai biyo baya. Ina neman tsari gare Ka daga sharrin wannan dare da abin da zai biyo baya. Ya Ubangijina, ina neman tsari gare Ka daga kasala da munin tsufa. Ya Ubangijina, ina neman tsari gare Ka daga azabar Wuta da azabar kabari.",
 "dua-000085": "Ya Allah, da Kai muke shiga safiya, da Kai muke shiga maraice. Da Kai muke rayuwa, da Kai muke mutuwa, kuma zuwa gare Ka ne tashinmu.",
 "dua-000086": "Ya Allah, da Kai muke shiga maraice, da Kai muke shiga safiya. Da Kai muke rayuwa, da Kai muke mutuwa, kuma zuwa gare Ka ne komawarmu.",
 "dua-000087": "Ya Allah, Kai ne Ubangijina, babu abin bautawa da gaskiya sai Kai. Kai ne Ka halicce ni, ni kuma bawanKa ne, kuma ina tsayawa a kan alkawarinKa da yarjejeniyarKa gwargwadon iyawata. Ina neman tsari gare Ka daga sharrin abin da na aikata. Ina yarda da ni'imarKa a kaina, kuma ina yarda da zunubina, don haka ka gafarta mini, domin babu wanda yake gafarta zunubai sai Kai.",
 "dua-000088": "Ya Allah, na shiga safiya, kuma ina kiran Ka, da masu ɗauke da Kursiyinka, da mala'ikunKa, da dukkan halittarKa, su shaida cewa Kai ne Allah. Babu abin bautawa da gaskiya sai Kai Kaɗai, babu abokin tarayya gare Ka, kuma Muhammadu bawanKa ne kuma Manzonka ne.",
 "dua-000089": "Ya Allah, na shiga maraice, kuma ina kiran Ka, da masu ɗauke da Kursiyinka, da mala'ikunKa, da dukkan halittarKa, su shaida cewa Kai ne Allah. Babu abin bautawa da gaskiya sai Kai Kaɗai, babu abokin tarayya gare Ka, kuma Muhammadu bawanKa ne kuma Manzonka ne.",
 "dua-000090": "Ya Allah, duk wata ni'ima da ta zo mini, ko ga wani daga cikin halittarKa, a safiyar yau, daga Kai kaɗai take, babu abokin tarayya gare Ka. Gare Ka ne yabo, kuma gare Ka ne godiya.",
 "dua-000091": "Ya Allah, duk wata ni'ima da ta zo mini, ko ga wani daga cikin halittarKa, a yammacin yau, daga Kai kaɗai take, babu abokin tarayya gare Ka. Gare Ka ne yabo, kuma gare Ka ne godiya.",
 "dua-000092": "Ya Allah, ka ba jikina lafiya. Ya Allah, ka ba jina lafiya. Ya Allah, ka ba idanuna lafiya. Babu abin bautawa da gaskiya sai Kai. Ya Allah, ina neman tsari gare Ka daga kafirci da talauci, kuma ina neman tsari gare Ka daga azabar kabari. Babu abin bautawa da gaskiya sai Kai.",
 "dua-000093": "Allah ya isar mini. Babu abin bautawa da gaskiya sai Shi. A gare Shi na dogara, kuma Shi ne Ubangijin Kursiyi mai girma.",
 "dua-000094": "Ya Allah, ina roƙonKa gafara da lafiya a duniya da lahira. Ya Allah, ina roƙonKa gafara da lafiya a cikin al'amuran addinina da na duniyata, da iyalina, da dukiyata. Ya Allah, ka rufe mini kurakurai, ka kwantar mini da fargabata. Ya Allah, ka kiyaye ni daga gabana da bayana, da dama da hagu, da sama, kuma ina neman tsari gare Ka kada a haɗiye ni da ƙasa.",
 "dua-000095": "Ya Allah, Masani ga gaibi da abin gani, Mahaliccin sammai da ƙasa, Ubangiji kuma Sarkin kowane abu, ina shaida cewa babu abin bautawa da gaskiya sai Kai. Ina neman tsari gare Ka daga sharrin raina, da sharrin shaiɗan da shirkarsa, da daga aikata wani laifi a kan raina, ko jawo hakan a kan wani Musulmi.",
 "dua-000096": "Da sunan Allah, wanda tare da sunansa babu abin da zai cutar a ƙasa ko a sama. Shi ne Mai ji, Masani.",
 "dua-000097": "Na yarda da Allah a matsayin Ubangiji, da Musulunci a matsayin addini, da Muhammadu a matsayin Annabi.",
 "dua-000098": "Ya Mai rai har abada, Ya Mai tsayuwa da kanKa, kuma Mai riƙe kowa, da rahamarKa nake neman taimako. Ka gyara mini dukkan al'amurana, kada Ka bar ni ga kaina ko da na ɗan lokaci kamar kiftawar ido.",
 "dua-000099": "Mun shiga safiya, kuma duk mulki na Allah ne, Ubangijin talikai. Ya Allah, ina roƙonKa alherin wannan yini: nasararsa, da cin nasara, da haskensa, da albarkarsa, da shiriyarsa. Ina neman tsari gare Ka daga sharrin da ke cikinsa da sharrin da ke biye da shi.",
 "dua-000100": "Mun shiga maraice, kuma duk mulki na Allah ne, Ubangijin talikai. Ya Allah, ina roƙonKa alherin wannan dare: nasararsa, da cin nasara, da haskensa, da albarkarsa, da shiriyarsa. Ina neman tsari gare Ka daga sharrin da ke cikinsa da sharrin da ke biye da shi.",
 "dua-000101": "Mun shiga safiya bisa tafarkin Musulunci, da kalmar tsarkakken imani, da addinin Annabinmu Muhammadu (tsira da amincin Allah su tabbata a gare shi), da akidar kakanmu Ibrahim, wanda ya kasance mai karkata zuwa gaskiya, Musulmi mai miƙa wuya ga Allah, kuma ba ya cikin masu haɗa abokan tarayya da Allah.",
 "dua-000102": "Mun shiga maraice bisa tafarkin Musulunci, da kalmar tsarkakken imani, da addinin Annabinmu Muhammadu (tsira da amincin Allah su tabbata a gare shi), da akidar kakanmu Ibrahim, wanda ya kasance mai karkata zuwa gaskiya, Musulmi mai miƙa wuya ga Allah, kuma ba ya cikin masu haɗa abokan tarayya da Allah.",
 "dua-000103": "Tsarki ya tabbata ga Allah, kuma ina yabonSa.",
 "dua-000104": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome.",
 "dua-000105": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome.",
 "dua-000106": "Tsarki ya tabbata ga Allah, kuma ina yabonSa adadin halittunSa, da yardarSa, da nauyin Kursiyinsa, da tawadar kalmominSa.",
 "dua-000107": "Ya Allah, ina roƙonKa ilimi mai amfani, da arziki mai kyau, da ayyuka karɓaɓɗu.",
 "dua-000108": "Ina neman gafarar Allah, kuma ina komawa gare Shi da tuba.",
 "dua-000109": "Ina neman tsari da cikakkun kalmomin Allah daga sharrin abin da Ya halitta.",
 "dua-000110": "Ya Allah, ka aika da salati da aminci ga Annabinmu Muhammadu.",
 "dua-000111": "Da sunan Allah, Mai rahama, Mai jinƙai. 112:1 Ka ce: Shi ne Allah, Ɗaya. 112:2 Allah, Wanda dukkan halitta ke nufinSa. 112:3 Ba Ya haifuwa, kuma ba a haife Shi ba. 112:4 Babu wani abu mai kama da Shi. Da sunan Allah, Mai rahama, Mai jinƙai. 113:1 Ka ce: Ina neman tsari da Ubangijin safiya, 113:2 daga sharrin abin da Ya halitta, 113:3 daga sharrin duhu idan ya yi yawa, 113:4 daga sharrin masu busawa cikin ƙulli, 113:5 da sharrin mai hassada idan ya yi hassada. Da sunan Allah, Mai rahama, Mai jinƙai. 114:1 Ka ce: Ina neman tsari da Ubangijin mutane, 114:2 Sarkin mutane, 114:3 Abin bautawar mutane, 114:4 daga sharrin mai waswasi mai ja da baya, 114:5 wanda yake waswasi a cikin zukatan mutane, 114:6 daga aljanu da mutane.",
 "dua-000112": "Allah! Babu abin bautawa da gaskiya sai Shi, Mai rai, Mai tsayar da komai. Barci ko bacci ba sa kama Shi. Duk abin da ke cikin sammai da ƙasa nasa ne. Wa zai iya yin ceto a wurinSa sai da izininSa? Yana sane da abin da ke gabansu da abin da ke bayansu, kuma ba sa sanin komai daga iliminSa sai abin da Ya so. KursiyyinSa ya kewaye sammai da ƙasa, kuma kiyaye su ba ya gajiyar da Shi. Shi ne Maɗaukaki, Mai girma.",
 "dua-000113": "285 Manzo ya yi imani da abin da aka saukar masa daga Ubangijinsa, haka kuma muminai. Kowane yana imani da Allah, da mala'ikunSa, da littattafanSa, da manzanninSa. \"Ba ma bambanta tsakanin ɗaya daga cikin manzanninSa.\" Suna cewa: \"Mun ji, kuma mun yi biyayya. Ubangijinmu, muna neman gafararKa, kuma zuwa gare Ka ne makoma.\" 286 Allah ba ya ɗora wa rai abin da ba zai iya ɗauka ba. Yana samun abin da ya aikata na alheri, kuma yana ɗaukar abin da ya aikata na sharri. \"Ubangijinmu, kada Ka kama mu idan mun manta ko muka yi kuskure. Ubangijinmu, kada Ka ɗora mana nauyi kamar wanda Ka ɗora wa waɗanda suka gabace mu. Ubangijinmu, kada Ka ɗora mana abin da ba mu da ƙarfin ɗauka. Ka yafe mana, ka gafarta mana, ka yi mana rahama. Kai ne Majiɓincinmu, don haka ka taimake mu a kan mutane kafirai.\"",
 "dua-000114": "Da sunanKa, Ubangijina, nake kwanciya, kuma da sunanKa nake tashi. Idan Ka karɓi raina, to ka yi mata rahama, idan kuma Ka mayar mini da ita, to ka kiyaye ta kamar yadda Kake kiyaye bayinKa masu adalci.",
 "dua-000115": "Ya Allah, lalle Kai ne Ka halicci raina, kuma Kai ne zaka karɓi ranta. Rayuwarta da mutuwarta na gare Ka. Idan Ka sa ta rayu, to ka kiyaye ta, idan kuma Ka karɓi ranta, to ka gafarta mata. Ya Allah, ina roƙonKa lafiya.",
 "dua-000116": "Ya Allah, ka kiyaye ni daga azabarKa a ranar da bayinKa za a tashe su.",
 "dua-000117": "Da sunanKa Ya Allah, ina rayuwa, kuma ina mutuwa.",
 "dua-000118": "Tsarki ya tabbata ga Allah.",
 "dua-000119": "Dukkan godiya ta tabbata ga Allah.",
 "dua-000120": "Allah ne Mafi girma.",
 "dua-000121": "Ya Allah, Ubangijin sammai bakwai da Kursiyi mai girma, Ubangijinmu kuma Ubangijin kowane abu, Mai fasa iri da kwaya, Mai saukar da Attaura da Injila da Furƙani, ina neman tsari gare Ka daga sharrin kowane abu da Kai ka riƙe bisa goshinsa, watau Kana da cikakken iko a kansa. Ya Allah, Kai ne Na farko, don haka babu wani abu kafinKa, kuma Kai ne Na ƙarshe, don haka babu wani abu bayanKa. Kai ne Mafi bayyana, don haka babu wani abu sama da Kai, kuma Kai ne Mafi ɓoye, don haka babu wani abu kusa da Kai fiye da Kai. Ka biya mana bashinmu, ka kuma kiyaye mu daga talauci.",
 "dua-000122": "Dukkan godiya ta tabbata ga Allah, wanda Ya ciyar da mu, Ya shayar da mu, Ya ishe mu, kuma Ya ba mu mafaka. Domin da yawa ba su da wanda zai ishe su, ko ya ba su mafaka.",
 "dua-000123": "Ya Allah, Masani ga gaibi da abin gani, Mahaliccin sammai da ƙasa, Ubangiji kuma Sarkin kowane abu, ina shaida cewa babu abin bautawa da gaskiya sai Kai. Ina neman tsari gare Ka daga sharrin raina, da sharrin shaiɗan da shirkarsa, da daga aikata wani laifi a kan raina, ko jawo hakan a kan wani Musulmi.",
 "dua-000124": "Ya Allah, na miƙa raina gare Ka, kuma na miƙa al'amarina gare Ka, kuma na karkata fuskata zuwa gare Ka, kuma na dogara gare Ka gaba ɗaya, cikin bege da tsoronKa. Lalle babu mafaka, kuma babu wurin tsira daga gare Ka sai a wurinKa. Na yi imani da Littafinka da ka saukar, da Annabinka da ka aiko.",
 "dua-000125": "Babu abin bautawa da gaskiya sai Allah, Ɗaya, Al-Qahhar. Ubangijin sammai da ƙasa da abin da ke tsakaninsu, Maɗaukaki cikin iko, Mai yawan gafara.",
 "dua-000126": "Ina neman tsari da cikakkun kalmomin Allah daga fushinSa da azabarSa, da sharrin bayinSa, da hargitsin shaiɗanu da bayyanarsu.",
 "dua-000127": "Ya Allah, ka shiryar da ni tare da waɗanda Ka shiryar, ka gafarta mini tare da waɗanda Ka gafarta wa, ka zama majiɓincina tare da waɗanda Kake majiɓinci a gare su, kuma ka albarkaci abin da Ka ba ni. Ka kiyaye ni daga sharrin da Ka ƙaddara, domin lalle Kai ne Ka ƙaddara, babu wanda zai ƙaddara a kanKa. Lalle wanda Ka ba da goyon baya ba zai taɓa wulakanta ba, kuma wanda Ka ɗauka maƙiyi ba zai taɓa samun daraja ba. Ya Ubangijinmu, Albarkacin Kai, kuma Mai ɗaukaka ne Kai.",
 "dua-000128": "Ya Allah, ina neman tsari da yardarKa daga fushinKa, da gafararKa daga azabarKa, kuma ina neman tsari gare Ka daga Gare Ka. Ba zan iya ƙidaya yabonKa ba. Kai kamar yadda Ka yabi kanKa ne.",
 "dua-000129": "Ya Allah, Kai muke bautawa, gare Ka muke yin sallah da sujjada, zuwa gare Ka muke gaggawa, kuma Kai muke bauta wa. Muna fatan rahamarKa, kuma muna tsoron azabarKa, lalle azabarKa za ta sauka a kan kafirai. Ya Allah, muna neman taimakonKa da gafararKa, muna yabonKa da dukkan alheri, kuma ba mu kafirta da Kai ba. Mun yi imani da Kai, kuma mun miƙa wuya gare Ka, kuma muna barin da ƙin waɗanda suka kafirta da Kai.",
 "dua-000130": "Tsarki ya tabbata ga Sarki, Mai tsarki.",
 "dua-000131": "Ubangijin mala'iku da Ruhu.",
 "dua-000132": "Ya Allah, ni bawanKa ne, ɗan bawanKa, ɗan baiwarKa. Goshina yana hannunKa, umarninKa a kaina yana aiki har abada, hukuncinKa a kaina yana da adalci. Ina roƙonKa da kowane suna naKa, wanda Ka sa wa kanKa, ko Ka saukar a cikin LittafinKa, ko Ka koya wa wani daga cikin halittarKa, ko Ka ajiye shi a ilimin gaibi a wurinKa. Ka sa Alƙur'ani ya zama rayuwar zuciyata, da hasken ƙirjina, da kawar da baƙin cikina, da saukar damuwata.",
 "dua-000133": "Ya Allah, ina neman tsari gare Ka daga damuwa da baƙin ciki, da rauni da kasala, da rowa da rashin jarumta, da nauyin bashi, da kuma mamayar mutane.",
 "dua-000134": "Babu abin bautawa da gaskiya sai Allah Mai haƙuri. Babu abin bautawa da gaskiya sai Allah, Ubangijin Kursiyi mai girma. Babu abin bautawa da gaskiya sai Allah, Ubangijin sammai, Ubangijin ƙasa, da Ubangijin Kursiyi mai daraja.",
 "dua-000135": "Ya Allah, rahamarKa nake fata, don haka kada Ka bar ni ina kula da al'amurana ko da na ɗan lokaci kamar kiftawar ido, kuma ka gyara mini dukkan al'amurana. Babu abin bautawa da gaskiya sai Kai.",
 "dua-000136": "Babu abin bautawa da gaskiya sai Kai. Tsarki ya tabbata a gare Ka, lalle ni na kasance daga cikin azzalumai.",
 "dua-000137": "Allah, Allah ne Ubangijina, ban haɗa komai da Shi ba.",
 "dua-000138": "Ya Allah, muna sanya Ka a gabansu, kuma muna neman tsari gare Ka daga sharrinsu.",
 "dua-000139": "Ya Allah, Kai ne mai goyon bayana, kuma Kai ne mai taimakona. Da Kai nake motsawa, da Kai nake kai hari, da Kai nake yaƙi.",
 "dua-000140": "Allah ya ishe mu, kuma Shi mai kyau ne wakili.",
 "dua-000141": "Ya Allah, Ubangijin sammai bakwai, Ubangijin Kursiyi mai girma, ka zama mini mai goyon baya a kan [wane mutum] da mataimakansa daga cikin halittarKa, don kada ɗaya daga cikinsu ya zage ni, ko ya zalunce ni. Girma ta tabbata ga goyon bayanKa, kuma daukakar yabonKa tana da girma. Babu abin bautawa da gaskiya sai Kai.",
 "dua-000142": "Allah ne Mafi girma, Ya fi dukkan halittarSa girma. Ya fi abin da ake tsoro da firgita girma. Ina neman tsari da Allah, wanda babu abin bautawa da gaskiya sai Shi. Shi ne Wanda Yake riƙe sammai bakwai kada su faɗi a kan ƙasa sai da izininSa. [Ina neman tsari gare Ka, ya Allah] daga sharrin bawanKa [sunan mutumin], da mataimakansa, da magoya bayansa, da masu biye masa daga aljanu da mutane. Ya Allah, ka zama mini goyon baya daga sharrinsu. Girma ta tabbata ga yabonKa, kuma daukakar goyon bayanKa tana da girma. Albarka ta tabbata ga sunanKa, babu abin bautawa da gaskiya sai Kai.",
 "dua-000143": "Ya Allah, Mai saukar da Littafi, Mai saurin lissafi, ka ci nasara a kan ƙungiyoyin yaƙi. Ya Allah, ka ci nasara a kansu, ka girgiza su.",
 "dua-000144": "Ya Allah, ka kiyaye ni daga gare su da abin da Ka zaɓa.",
 "dua-000145": "Na yi imani da Allah da ManzonSa.",
 "dua-000146": "Shi ne Na farko da Na ƙarshe, Mai bayyanawa da Mai ɓoyewa, kuma Shi Masani ne ga kowane abu.",
 "dua-000147": "Ya Allah, ka sa abin da ke halal ya isar mini, ya fi abin da ke haram, kuma ka wadatar da ni da falalarKa daga bukatar wasu.",
 "dua-000148": "Ya Allah, ina neman tsari gare Ka daga damuwa da baƙin ciki, da rauni da kasala, da rowa da rashin jarumta, da nauyin bashi, da kuma mamayar mutane.",
 "dua-000149": "Ina neman tsari da Allah daga shaiɗan la'ananne.",
 "dua-000150": "Ya Allah, babu sauƙi sai a cikin abin da Ka sa ya zama mai sauƙi, kuma Kai, idan Ka so, kana mai da wahala ta zama mai sauƙi.",
 "dua-000151": "Allah ya ƙaddara, kuma abin da Ya so, Yana yi.",
 "dua-000152": "Allah ya albarkaci yaron da aka ba ka, ya sa ka iya gode wa Mai bayarwa, ya sa yaron ya kai girma, kuma ya albarkace ka da biyayyarsa.",
 "dua-000153": "Allah ya albarkace ka, ya zubo maka albarkarSa, ya ba ka lada da alheri, ya ba ka irin wannan albarka, kuma ya ƙara maka lada.",
 "dua-000154": "Ina damƙa ku biyu ga kariyar kalmomin Allah cikakku daga kowane shaiɗan, da kowace dabba mai cutarwa, da kowane ido na hassada.",
 "dua-000155": "Babu damuwa, Allah ya sa wannan cuta ta zama tsarkakewa, in Allah ya so.",
 "dua-000156": "Ina roƙon Allah Maɗaukaki, Ubangijin Kursiyi mai girma, ya warkar da kai (sau 7). Mara lafiyan zai warke.",
 "dua-000157": "\"Ya Allah, ka gafarta mini, ka yi mini rahama, kuma ka haɗa ni da mafi ɗaukaka abokai.\"",
 "dua-000158": "\"Babu abin bautawa da gaskiya sai Allah, lalle mutuwa tana da raɗaɗi.\"",
 "dua-000159": "Babu abin bautawa da gaskiya sai Allah, Allah ne Mafi girma. Babu abin bautawa da gaskiya sai Allah, Shi kaɗai. Babu abin bautawa da gaskiya sai Allah, Shi kaɗai, babu abokin tarayya gare Shi. Babu abin bautawa da gaskiya sai Allah, gare Shi ne mulki da yabo. Babu abin bautawa da gaskiya sai Allah, babu dabara ko ƙarfi sai da taimakon Allah.",
 "dua-000160": "Babu abin bautawa da gaskiya sai Allah.",
 "dua-000161": "Lalle mu na Allah ne, kuma zuwa gare Shi ne komawarmu. Ya Allah, ka biya ni a cikin musibata, ka musanya mini da wani abu mafi alheri.",
 "dua-000162": "Ya Allah, ka gafarta wa [sunan mamacin], ka ɗaukaka darajarsa a cikin masu shiriya, ka zama mai maye gurbin waɗanda ya bari, kuma ka gafarta mana da shi, ya Ubangijin talikai. Ka faɗaɗa kabarinsa, ka haskaka masa shi.",
 "dua-000163": "Ya Allah, ka gafarta masa, ka yi masa rahama, ka yafe masa, ka karɓe shi da girma. Ka faɗaɗa masa shigowarsa, ka wanke shi da ruwa, da dusar ƙanƙara, da ƙanƙara, ka tsarkake shi daga zunubi kamar yadda ake tsarkake farin riga daga datti. Ka musanya masa gida da wani gida mafi kyau, da iyalinsa da wasu iyali mafi kyau, da matarsa da wata mata mafi kyau. Ka shigar da shi Aljanna, ka kiyaye shi daga azabar kabari da azabar Wuta.",
 "dua-000164": "Ya Allah, ka gafarta wa rayayyenmu da matattunmu, da waɗanda suke nan da waɗanda ba su nan, da ƙananan mu da manyanmu, da mazanmu da matanmu. Ya Allah, duk wanda Ka raya daga cikinmu, to ka sa ya rayu a kan Musulunci, kuma duk wanda Ka karɓa daga cikinmu, to ka sa ya mutu a kan imani. Ya Allah, kada Ka hana mu ladansa, kuma kada Ka bar mu mu ɓace bayansa.",
 "dua-000165": "Ya Allah, ga fulani (sunansa) yana cikin kariyarKa, don haka ka kiyaye shi daga jarabawar kabari da azabar Wuta. Lalle Kai mai cika alkawari ne, kuma mai gaskiya. Ka gafarta masa, ka yi masa rahama, lalle Kai ne Mai yawan gafara, Mai jinƙai.",
 "dua-000166": "Ya Allah, bawanKa kuma ɗan baiwarKa yana buƙatar rahamarKa, kai kuma ba ka buƙatar azabarsa. Idan ya kasance nagari, to ka ƙara masa lada, idan kuwa ya kasance mugu, to ka yi watsi da zunubansa.",
 "dua-000167": "Ya Allah, ka kiyaye shi daga azabar kabari.",
 "dua-000168": "Ya Allah, ka sa shi ya zama mai gaba da ajiyar ladan iyayensa, kuma mai ceto wanda ceton nasa ake karɓa. Ya Allah, ka sa ma'aunansu ya yi nauyi ta dalilinsa, ka ƙara musu lada ta dalilinsa. Ka haɗa shi da bayi nagari masu imani, ka sa shi a kulawar Ibrahim, ka kiyaye shi da rahamarKa daga azabar Wuta. Ka ba shi gida mafi alheri daga gidansa, da iyali mafi alheri daga iyalinsa. Ya Allah, ka gafarta wa magabatanmu, da 'ya'yanmu waɗanda suka riga mu mutuwa, da waɗanda suka riga mu cikin imani.",
 "dua-000169": "Ya Allah, ka sa shi a gabanmu ya zama mai gaba, kuma sanadin lada.",
 "dua-000170": "Lalle na Allah ne abin da Ya ɗauka, kuma nasa ne abin da Ya bayar. Kowane abu a wurinSa yana da ƙayyadadden lokaci. Don haka ki yi haƙuri, kuma ki nemi ladan Allah.",
 "dua-000171": "Allah ya ƙara maka lada, ya ta'azantar da kai a cikin rashin, kuma ya gafarta wa wanda ya rasu.",
 "dua-000172": "Da sunan Allah, kuma bisa sunnar Manzon Allah.",
 "dua-000173": "Ya Allah, ka gafarta masa. Ya Allah, ka ƙarfafa shi.",
 "dua-000174": "Salama ta tabbata a gare ku, ya ku mazaunan kaburbura, daga cikin mumini da Musulmi. Lalle mu, in Allah ya so, za mu haɗu da ku. [Allah ya yi wa waɗanda suka riga mu rahama, da waɗanda suke zuwa bayanmu.] Ina roƙon Allah lafiya a gare mu da ku.",
 "dua-000175": "Ya Allah, ina roƙonKa alherinta, kuma ina neman tsari gare Ka daga sharrinta.",
 "dua-000176": "Ya Allah, ina roƙonKa alherinta, da alherin da ke cikinta, da alherin da aka aiko ta da shi, kuma ina neman tsari gare Ka daga sharrinta, da sharrin da ke cikinta, da sharrin da aka aiko ta da shi.",
 "dua-000177": "Tsarki ya tabbata gare Shi, wanda tsawa ke bayyana tsarkinSa tare da yabonSa, haka kuma mala'iku saboda tsoronSa.",
 "dua-000178": "Ya Allah, ka sauko mana da ruwan sama mai amfani, mai taimako, mai lafiya, mai albarka, ba mai cutarwa ba, yanzu, ba daga baya ba.",
 "dua-000179": "Ya Allah, ka ba mu sauƙi. Ya Allah, ka ba mu sauƙi. Ya Allah, ka ba mu sauƙi.",
 "dua-000180": "Ya Allah, ka ba bayinKa da dabbobinKa ruwa, ka shimfiɗa rahamarKa, ka farfado da ƙasarKa matacciya.",
 "dua-000181": "Ya Allah, ya zama girgije mai amfani.",
 "dua-000182": "An ba mu ruwan sama ta falalar Allah da rahamarSa.",
 "dua-000183": "Ya Allah, ka sa ruwan sama ya sauka kewaye da mu, ba a kanmu ba. Ya Allah, ka sa ya sauka a kan makiyaya, da tuddai, da kwari, da tushen itatuwa.",
 "dua-000184": "Allah ne Mafi girma. Ya Allah, ka sa wata ya bayyana a kanmu cikin aminci, da imani, da salama, da Musulunci, da yardar duk abin da Kake so kuma Ka yarda da shi. Ubangijinmu da Ubangijinku Allah ne.",
 "dua-000185": "Ƙishirwa ta tafi, jijiyoyi sun shayu, kuma lada ta tabbata, in Allah ya so.",
 "dua-000186": "Ya Allah, ina roƙonKa ta hanyar rahamarKa wadda take rufe komai, ka gafarta mini.",
 "dua-000187": "Da sunan Allah.",
 "dua-000188": "Da sunan Allah, a farkonsa da ƙarshensa.",
 "dua-000189": "Ya Allah, ka albarkace shi a gare mu, kuma ka ba mu abinci mafi alheri daga gare shi.",
 "dua-000190": "Ya Allah, ka albarkace shi a gare mu, kuma ka ƙara mana daga gare shi.",
 "dua-000191": "Dukkan godiya ta tabbata ga Allah, wanda Ya ciyar da ni wannan, Ya azurta ni da shi ba tare da wani ƙarfi ko dabara daga gare ni ba.",
 "dua-000192": "Allah ya cancanci yabo mai yawa, mai kyau, mai albarka, yabo mara ƙarewa, yabo da ba za mu taɓa yin bankwana da shi ba, yabo da ba za a iya rabuwa da shi ba. Shi ne Ubangijinmu. Akwai wasu ra'ayoyi game da fahimtar wannan addu'a, daga cikinsu: Allah ya cancanci yabo mai yawa, mai kyau, mai albarka. Shi ne Wanda Yake isarwa, Yana ciyarwa, ba a ciyar da Shi ba. Wanda ake marmari, tare da abin da yake wurinSa, kuma Wanda ake buƙata. Shi ne Ubangijinmu.",
 "dua-000193": "Ya Allah, ka albarkaci abin da Ka azurta su da shi, ka gafarta musu, ka yi musu rahama.",
 "dua-000194": "Ya Allah, ka ciyar da wanda ya ciyar da ni, kuma ka shayar da wanda ya shayar da ni.",
 "dua-000195": "Bari masu azumi su karya azuminsu a gidanka, kuma masu tsoron Allah masu nagarta su ci abincinka, kuma mala'iku su yi maka salati.",
 "dua-000196": "Ina azumi, ina azumi.",
 "dua-000197": "Ya Allah, ka albarkaci 'ya'yan itatuwanmu a gare mu, ka albarkaci garinmu a gare mu, ka albarkaci sa'anmu a gare mu, kuma ka albarkaci mudd ɗinmu a gare mu.",
 "dua-000198": "Dukkan godiya ta tabbata ga Allah.",
 "dua-000199": "Allah ya yi maka rahama.",
 "dua-000200": "Allah ya shiryar da kai, ya gyara al'amuranka.",
 "dua-000201": "Allah ya shiryar da kai, ya gyara yanayinka.",
 "dua-000202": "Allah ya albarkaci matarka a gare ka, kuma ya albarkace ka, ya haɗa ku biyu cikin alheri.",
 "dua-000203": "Ya Allah, ina roƙonKa alherin da ke cikinta, da alherin da Ka sa ta karkata zuwa gare shi, kuma ina neman tsari gare Ka daga sharrin da ke cikinta, da sharrin da Ka sa ta karkata zuwa gare shi.",
 "dua-000204": "Da sunan Allah. Ya Allah, ka kiyaye shaiɗan daga gare mu, ka kiyaye shaiɗan daga abin da Ka albarkace mu da shi.",
 "dua-000205": "Ina neman tsari da Allah daga shaiɗan la'ananne.",
 "dua-000206": "Dukkan godiya ta tabbata ga Allah wanda Ya tsare ni daga abin da Ya jarabce ka da shi, kuma tabbas Ya fifita ni a kan mutane da yawa daga cikin halittarSa.",
 "dua-000207": "Ya Ubangijina, ka gafarta mini, ka karɓi tubata. Lalle Kai ne Mai karɓar tuba, Mai yawan gafara.",
 "dua-000208": "Tsarki ya tabbata a gare Ka, ya Allah, ina yabonKa. Ina shaida cewa babu abin bautawa da gaskiya sai Kai. Ina neman gafararKa, kuma ina tuba zuwa gare Ka.",
 "dua-000209": "Kai ma.",
 "dua-000210": "Allah ya saka maka da alheri.",
 "dua-000211": "Shi wanda ka ƙaunace ni saboda Shi, Ya ƙaunace ka.",
 "dua-000212": "Allah ya albarkace maka iyalinka da dukiyarka.",
 "dua-000213": "Allah ya albarkace maka iyalinka da dukiyarka. Lalle yabo da biya su ne ladan bashi.",
 "dua-000214": "Ya Allah, ina neman tsari gare Ka daga yin shirka da Kai da gangan, kuma ina neman gafararKa saboda abin da nake aikatawa ba da sani ba.",
 "dua-000215": "Allah ya albarkace su.",
 "dua-000216": "Ya Allah, babu tsinuwa sai ga Kai ka dogara, babu alheri sai alherinKa, kuma babu abin bautawa da gaskiya sai Kai.",
 "dua-000217": "Da sunan Allah, dukkan godiya ta tabbata ga Allah. Tsarki ya tabbata ga Wanda Ya sa mana wannan abin hawa, alhali ba za mu iya ba, kuma zuwa ga Ubangijinmu ne makomarmu. Dukkan godiya ta tabbata ga Allah, dukkan godiya ta tabbata ga Allah, dukkan godiya ta tabbata ga Allah. Allah ne Mafi girma, Allah ne Mafi girma, Allah ne Mafi girma. Tsarki ya tabbata a gare Ka, ya Allah, lalle ni na zalunci kaina, don haka ka gafarta mini, domin babu wanda yake gafarta zunubai sai Kai.",
 "dua-000218": "Allah ne Mafi girma, Allah ne Mafi girma, Allah ne Mafi girma. Tsarki ya tabbata ga Wanda Ya hore mana wannan, alhali ba mu da ikon sarrafa shi da kanmu. Lalle zuwa ga Ubangijinmu ne za mu koma. Ya Allah, muna roƙonKa a cikin tafiyarmu nan alheri da taƙawa, da ayyukan da suke yarda da Kai. Ya Allah, ka sauƙaƙa mana wannan tafiya, ka rage mana nisanta. Ya Allah, Kai ne Abokin tafiya, kuma Mai kula da iyali. Ya Allah, ina neman tsari gare Ka daga wahalar tafiya, da daga abubuwan baƙin ciki, da daga dawowa ka tarar da cuta a dukiyarmu ko iyalinmu.",
 "dua-000219": "Mun dawo, muna tuba, muna bauta, kuma muna yabon Ubangijinmu.",
 "dua-000220": "Ya Allah, Ubangijin sammai bakwai da duk abin da suka rufe, Ubangijin ƙasa bakwai da duk abin da suka ɗauka, Ubangijin shaiɗanu da duk waɗanda suke ɓatarwa, Ubangijin iska da duk abin da suka kwashe. Ina roƙonKa alherin wannan ƙauye, da alherin mazaunansa, da duk alherin da ke cikinsa, kuma ina neman tsari gare Ka daga sharrin wannan ƙauye, da sharrin mazaunansa, da duk sharrin da ke cikinsa.",
 "dua-000221": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo. Yana ba da rai, kuma Yana kashe, kuma Shi Mai rai ne, ba ya mutuwa. A hannunSa ne dukkan alheri, kuma Shi Mai iko ne a kan kome.",
 "dua-000222": "Da sunan Allah.",
 "dua-000223": "Ina damƙa ka a amincin Allah, wanda amincinSa ba ya ɓacewa.",
 "dua-000224": "Ina damƙa addininka, da amincinka, da ƙarshen ayyukanka a amincin Allah.",
 "dua-000225": "Allah ya ba ka taƙawa, ya gafarta zunubanka, kuma ya sauƙaƙa maka dukkan alheri duk inda kake.",
 "dua-000226": "Bari shaida ta zama shaida ga yabonmu ga Allah saboda falalarSa da ni'imominSa a kanmu. Ya Ubangijinmu, ka kiyaye mu, ka nuna mana alheri, kuma ka tseratar da mu daga kowane sharri. Ina neman tsari da Allah daga wuta.",
 "dua-000227": "Ina neman tsari da cikakkun kalmomin Allah daga sharrin da Ya halitta.",
 "dua-000228": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome. Mun dawo, muna tuba, muna bauta, kuma muna yabon Ubangijinmu. Allah ya cika alkawarinSa, ya taimaki bawanSa, kuma shi kaɗai ya kayar da ƙungiyoyin yaƙi.",
 "dua-000229": "Dukkan godiya ta tabbata ga Allah, wanda ta alherinSa ake kammala ayyuka nagari.",
 "dua-000230": "Dukkan godiya ta tabbata ga Allah a kowane hali.",
 "dua-000231": "Kai ma.",
 "dua-000232": "Ya Allah, ga kowane mumini da na zage shi, ka sa hakan ya zama sanadin kusantar da shi zuwa gare Ka a Ranar Tashin Kiyama.",
 "dua-000233": "Ina ɗaukar fulani [...] kuma Allah ne Mai lissafinsa. Ba na shaida wa kowa tsarki a gaban Allah.",
 "dua-000234": "Ya Allah, kada Ka kama ni saboda abin da suke faɗa, ka gafarta mini abin da ba su sani ba [kuma ka sa ni fiye da abin da suke zato].",
 "dua-000235": "Ga ni, ya Allah, ina amsa kiranKa, ga ni. Ga ni, babu abokin tarayya a gare Ka, ga ni. Lalle dukkan yabo, da ni'ima, da mulki na Kai ne. Babu abokin tarayya a gare Ka.",
 "dua-000236": "Ubangijinmu, ka ba mu alheri a duniya, da alheri a lahira, kuma ka kiyaye mu daga azabar Wuta.",
 "dua-000237": "Lalle Safa da Marwa suna daga alamomin Allah. Ina farawa da abin da Allah ya fara da shi.",
 "dua-000238": "Babu abin bautawa da gaskiya sai Allah. Allah ne Mafi girma.",
 "dua-000239": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki, kuma gare Shi ne yabo. Shi Mai iko ne a kan kome. Babu abin bautawa da gaskiya sai Allah Shi kaɗai. Ya cika alkawarinSa, ya taimaki bawanSa, kuma shi kaɗai ya kayar da ƙungiyoyin yaƙi.",
 "dua-000240": "Babu abin bautawa da gaskiya sai Allah, Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne yabo da mulki, kuma Shi Mai iko ne a kan kome.",
 "dua-000241": "Tsarki ya tabbata ga Allah.",
 "dua-000242": "Allah ne Mafi girma.",
 "dua-000243": "Da sunan Allah.",
 "dua-000244": "Ina neman tsari da Allah da ikonSa daga sharrin abin da nake ji da abin da nake tsoro.",
 "dua-000019": "Ya Allah, ka sa haske a cikin zuciyata, da haske a harshena, da haske a cikin kunnuwana, da haske a idanuna. Ka sa haske a samana, da haske a ƙasana, da haske a dama ta, da haske a hagu ta, da haske a gabana, da haske a bayana. Ka sa haske a raina, ka ƙara mini haske, ka girmama mini haske, ka ba ni haske, ka sa ni haske. Ya Allah, ka ba ni haske, ka sa haske a jijiyoyina, da haske a naman jikina, da haske a jinina, da haske a gashina, da haske a fatata. [Ya Allah, ka sa mini haske a kabarina, da haske a ƙasusuwana.] [Ka ƙara mini ƙari da haske, ka ƙara mini ƙari da haske, ka ƙara mini ƙari da haske.] [Ka ba ni haske bisa haske.]",
 "dua-000245": "Babu abin bautawa da gaskiya sai Allah.",
 "dua-000246": "Da sunan Allah, Allah ne Mafi girma. Ya Allah, daga gare Ka yake kuma naKa ne. Ya Allah, ka karɓi wannan daga gare ni.",
 "dua-000247": "Ina neman tsari da cikakkun kalmomin Allah, waɗanda babu wani mai kyau ko mugu da zai ƙetare su, daga dukkan sharrin da Ya halitta, da Ya ƙirƙira, da Ya samar. Ina neman tsari daga sharrin da yake sauka daga sama, da sharrin da yake hawa zuwa gare ta. Ina neman tsari daga sharrin da yake yaɗuwa a ƙasa, da sharrin da yake fitowa daga cikinta. Kuma ina neman tsari daga sharrin fitintinun dare da rana, da sharrin mai ziyara da dare, sai wanda ya kawo alheri, Ya Mai rahama.",
 "dua-000248": "Ina neman gafarar Allah, wanda babu abin bautawa da gaskiya sai Shi, Mai rai har abada, Mai tsayuwa da kansa, kuma Mai riƙe kowa, kuma ina komawa gare Shi da tuba.",
 "dua-000249": "Tsarki ya tabbata ga Allah, kuma ina yabonSa.",
 "dua-000250": "Babu abin bautawa da gaskiya sai Allah Shi kaɗai, babu abokin tarayya gare Shi. Gare Shi ne mulki da yabo, kuma Shi Mai iko ne a kan kome.",
 "dua-000251": "Tsarki ya tabbata ga Allah, kuma ina yabonSa. Tsarki ya tabbata ga Allah, Mai girma.",
 "dua-000252": "Tsarki ya tabbata ga Allah, kuma dukkan godiya ta tabbata ga Allah. Babu abin bautawa da gaskiya sai Allah, kuma Allah ne Mafi girma.",
 "dua-000253": "Tsarki ya tabbata ga Allah, Mai girma, kuma ina yabonSa.",
 "dua-000254": "Babu dabara ko ƙarfi sai da taimakon Allah.",
 "dua-000255": "Tsarki ya tabbata ga Allah, dukkan godiya ta tabbata ga Allah. Babu abin bautawa da gaskiya sai Allah, kuma Allah ne Mafi girma.",
 "dua-000256": "Babu abin bautawa da gaskiya sai Allah, Shi kaɗai, babu abokin tarayya gare Shi. Allah ne Mafi girma, babba ƙwarai. Godiya mai yawa ta tabbata ga Allah. Tsarki ya tabbata ga Allah, Ubangijin talikai. Babu dabara ko ƙarfi sai ta Allah, Mai iko, Mai hikima.",
 "dua-000257": "Ya Allah, ka gafarta mini, ka yi mini rahama, ka shiryar da ni, ka azurta ni.",
 "dua-000258": "Ya Allah, ka gafarta mini, ka yi mini rahama, ka shiryar da ni, ka ba ni lafiya, ka azurta ni.",
 "dua-000259": "Dukkan godiya ta tabbata ga Allah.",
 "dua-000260": "Babu abin bautawa da gaskiya sai Allah.",
 "dua-000261": "'Tsarki ya tabbata ga Allah', da 'Godiya ta tabbata ga Allah', da 'Babu abin bautawa da gaskiya sai Allah', da 'Allah ne Mafi girma', da 'Babu dabara ko ƙarfi sai da taimakon Allah'.",
 "dua-000004": "190 Lalle a cikin halittar sammai da ƙasa, da sauyawar dare da rana, akwai ayoyi ga masu hankali. 191 Waɗanda suke ambaton Allah a tsaye, da zaune, da kwance a gefensu, kuma suke tunani game da halittar sammai da ƙasa: \"Ya Ubangijinmu, ba ka halicci wannan a banza ba. Tsarki ya tabbata a gare Ka, ka kiyaye mu daga azabar Wuta.\" 192 \"Ya Ubangijinmu, duk wanda Ka shigar da shi Wuta, to lalle Ka wulakanta shi, kuma azzalumai ba su da mataimaka.\" 193 \"Ya Ubangijinmu, mun ji mai kira yana kira zuwa ga imani, yana cewa: Ku yi imani da Ubangijinku, sai muka yi imani. Ya Ubangijinmu, ka gafarta mana zunubanmu, ka shafe mana kurakuranmu, ka karɓe mu tare da nagargarun bayi.\" 194 \"Ya Ubangijinmu, ka ba mu abin da Ka yi mana alkawari ta hannun manzanninKa, kuma kada Ka wulakanta mu a Ranar Tashin Kiyama. Lalle Kai ba ka saɓa alkawari.\" 195 Ubangijinsu ya amsa musu: \"Ba zan ɓata aikin kowane ɗaya daga cikinku ba, namiji ko mace; ku ɗaya ne daga wani. Zan shafe kurakuran waɗanda suka yi hijira, aka fitar da su daga gidajensu, aka cutar da su saboda Ni, suka yi yaƙi, ko aka kashe su, lalle zan shigar da su gonaki da koguna ke gudana a ƙarƙashinsu, a matsayin lada daga wurin Allah. A wurin Allah ne kyakkyawar lada take.\" 196 Kada 'yancin da kafirai suke yawo da shi a ƙasa ya ruɗe ka. 197 Jin daɗi ne na ɗan lokaci kawai; sa'an nan Wuta ce makomarsu, kuma tir da wurin kwana! 198 Amma waɗanda suka ji tsoron Ubangijinsu, suna da gonaki da koguna ke gudana a ƙarƙashinsu, suna dawwama a cikinsu, karɓuwa daga wurin Allah. Abin da yake wurin Allah ya fi ga masu nagarta. 199 Daga cikin Ahlul Kitab akwai waɗanda suke imani da Allah, da abin da aka saukar muku, da abin da aka saukar musu. Suna ƙasƙantar da kansu ga Allah, ba sa sayar da ayoyin Allah da ƙaramin farashi. Ladansu yana wurin Ubangijinsu; lalle Allah mai saurin lissafi ne. 200 Ya ku waɗanda kuka yi imani, ku yi haƙuri, ku fi juna haƙuri, ku kasance cikin shiri, kuma ku ji tsoron Allah domin ku ci nasara.",
 "dua-000041": "Sammai da ƙasa da abin da ke tsakaninsu suna cike da yabonKa, kuma duk abin da Kake so yana cike da yabonKa. Ya Mai yabo da daraja, gaskiya ce abin da bawa ya faɗa game da Kai, kuma dukkanmu bayinKa ne. Ya Allah, babu wanda zai hana abin da Ka ba da, kuma babu wanda zai ba da abin da Ka hana, kuma dukiya ko daraja ba za su amfani mai su a gabanKa ba, domin dukkan dukiya da daraja daga gare Ka suke. Wannan addu'a ana yin ta ne a matsayin zaɓi, tare da wadda ta gabata kawai.",
 "dua-000042": "Tsarki ya tabbata ga Ubangijina, Maɗaukaki.",
 "dua-000043": "Tsarki ya tabbata a gare Ka, ya Allah, Ubangijinmu, ina yabonKa. Ya Allah, ka gafarta mini.",
 "dua-000044": "Tsarkakakke ne kuma mai tsarki, Ubangijin mala'iku da Ruhu, watau Jibrilu.",
 "dua-000045": "Ya Allah, gare Ka na yi sujjada, kuma da Kai na yi imani, kuma gare Ka na miƙa wuya. Fuskata ta yi sujjada ga Wanda Ya halicce ta, Ya siffanta ta, Ya fito da gaɓoɓinta na ji da gani. Albarkacin Allah, Mafi kyawun masu halitta."
};
